import nx from '@nx/eslint-plugin';
import baseConfig from '../../eslint.config.mjs';

/**
 * React Native app: the ui-kit HTML-tag ban (`domainUiKitHtmlBan`) is not spread here on purpose.
 * The app renders React Native primitives and cannot load ui-kit at all (see the import bans below
 * and the `scope:attendance` boundary in the root config).
 */
export default [
  // Native projects are generated by `expo prebuild` and never linted.
  { ignores: ['android/**', 'ios/**', '.expo/**'] },
  ...baseConfig,
  ...nx.configs['flat/react'],
  {
    files: ['**/*.ts', '**/*.tsx'],
    rules: {
      // expo-status-bar's `style` prop is a string ('light' | 'dark' | 'auto'), not a style object.
      'react/style-prop-object': ['warn', { allow: ['StatusBar'] }],
      'no-restricted-imports': [
        'error',
        {
          patterns: [
            {
              // The module-boundary rule already stops core/*, plugins/* and ui-kit. These three
              // are type:platform, so they pass that rule but cannot run on React Native.
              group: [
                '@inventory-platform/ui-kit',
                '@inventory-platform/ui-kit/*',
                '@inventory-platform/api-client',
                '@inventory-platform/api-client/*',
                '@inventory-platform/shell',
                '@inventory-platform/shell/*',
              ],
              message:
                'The Attendance app runs on React Native: ui-kit (DOM + CSS modules), api-client (axios + localStorage) and shell (react-router) cannot load here. Use @inventory-platform/attendance-protocol and the app\u2019s own src/api and src/state modules.',
            },
            {
              // Allow-list: the only workspace packages the app may depend on.
              group: [
                '@inventory-platform/*',
                '@inventory-platform/*/*',
                '!@inventory-platform/attendance-protocol',
                '!@inventory-platform/contracts',
              ],
              message:
                'Only @inventory-platform/attendance-protocol and @inventory-platform/contracts (types) may be imported from the workspace (apps/attendance/README.md, Boundaries).',
            },
          ],
        },
      ],
    },
  },
];
